const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.materializacion.ejecutar_materializacion() (Python, unica
// autoridad de esta logica). Este nodo NUNCA decide nada de negocio: solo
// empaqueta lo que ya vino de la rama fixture o drive_readonly (ver
// RUTEAR - source_mode (materializacion)).
const payload = {
  cierres_ingesta: t.cierres_ingesta || [],
  params: {
    base_dir_dev: t.base_dir_dev,
    origen_cierres_dir: t.origen_cierres_dir,
    ruta_maestro_origen: t.ruta_maestro_origen,
    ruta_plantilla_origen: t.ruta_plantilla_origen,
    markers_origen_dir: t.markers_origen_dir || null,
    mes_rango: t.mes_rango,
  },
};

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_materializacion_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_materializacion_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

// Modo fixture: los origenes ya vienen armados desde el trigger, sin
// tocar Drive. Ningun cambio de comportamiento respecto a FASE 5-9.
const t = $('ENTRADA (Execute Workflow Trigger)').first().json;
return [{
  json: {
    cierres_ingesta: t.cierres_ingesta || [],
    base_dir_dev: t.base_dir_dev,
    origen_cierres_dir: t.origen_cierres_dir,
    ruta_maestro_origen: t.ruta_maestro_origen,
    ruta_plantilla_origen: t.ruta_plantilla_origen,
    markers_origen_dir: t.markers_origen_dir || null,
    mes_rango: t.mes_rango,
  },
}];

// Solo filtra/reestructura: NUNCA decide REGLA G aqui (eso ya lo decidio
// v3.ingesta en Python, modulo 01). Descarga UNICAMENTE los cierres que
// llegaron ENCONTRADO con un drive_file_id EXACTO -- nunca AMBIGUO ni
// SIN_ARCHIVO, nunca "el primero" de una lista. Con cierres_ingesta=[]
// (prueba real de FASE 10A) esto produce 0 items a proposito.
const trigger = $('RUTEAR - source_mode (materializacion)').first().json;
const cierres = trigger.cierres_ingesta || [];
const encontrados = cierres.filter((c) => c.estado_ingesta === 'ENCONTRADO' && c.drive_file_id);
return encontrados.map((c) => ({ json: { drive_file_id: c.drive_file_id, archivo_esperado: c.archivo_esperado } }));

// Combina las 4 ramas reales (maestro/plantilla/markers/cierres) en los
// MISMOS nombres de parametro que ya usaba v3.materializacion en modo
// fixture -- CERO cambios en v3/materializacion.py: el mecanismo de copia
// (shutil.copyfile) es identico, solo cambia DE DONDE viene el origen.
const trigger = $('RUTEAR - source_mode (materializacion)').first().json;
const maestro = $('GUARDAR - Maestro real a disco').first();
const plantilla = $('GUARDAR - Plantilla real a disco').first();

return [{
  json: {
    cierres_ingesta: trigger.cierres_ingesta || [],
    base_dir_dev: trigger.base_dir_dev,
    origen_cierres_dir: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/cierres_origen',
    ruta_maestro_origen: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/maestro_origen/' + maestro.binary.data.fileName,
    ruta_plantilla_origen: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/plantilla_origen/' + plantilla.binary.data.fileName,
    markers_origen_dir: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/markers_origen',
    mes_rango: trigger.mes_rango,
  },
}];

